/**
 * Extracts plain text strings from a PDF buffer generated by @react-pdf/renderer.
 * Decompresses FlateDecode streams and collects text from Tj and TJ operators.
 */
function decodeHexPdfString(hex: string): string {
  let str = "";
  for (let i = 0; i < hex.length; i += 2) {
    const code = parseInt(hex.slice(i, i + 2), 16);
    if (!isNaN(code)) {
      str += String.fromCharCode(code);
    }
  }
  return str;
}

/**
 * Extracts plain text strings from a PDF buffer generated by @react-pdf/renderer.
 * Decompresses FlateDecode streams and collects text from hex-encoded and ASCII Tj and TJ operators.
 */
function extractPdfText(pdfBuffer: Buffer): string {
  const binary = pdfBuffer.toString("binary");
  const decompressedStreams: string[] = [];

  let pos = 0;
  while (true) {
    const streamStart = binary.indexOf("stream", pos);
    if (streamStart === -1) break;

    // The stream data starts after "stream" followed by \r\n or \n
    let dataStart = streamStart + 6;
    if (binary.charCodeAt(dataStart) === 0x0d && binary.charCodeAt(dataStart + 1) === 0x0a) {
      dataStart += 2;
    } else if (binary.charCodeAt(dataStart) === 0x0a) {
      dataStart += 1;
    }

    const streamEnd = binary.indexOf("endstream", dataStart);
    if (streamEnd === -1) break;

    let dataEnd = streamEnd;
    if (binary.charCodeAt(dataEnd - 1) === 0x0a) {
      dataEnd -= 1;
      if (binary.charCodeAt(dataEnd - 1) === 0x0d) {
        dataEnd -= 1;
      }
    }

    const raw = Buffer.from(binary.slice(dataStart, dataEnd), "binary");
    try {
      const decompressed = zlib.inflateSync(raw).toString("latin1");
      decompressedStreams.push(decompressed);
    } catch {
      decompressedStreams.push(raw.toString("latin1"));
    }

    pos = streamEnd + 9;
  }

  const combinedContent = decompressedStreams.join("\n");
  const textTokens: string[] = [];

  // Match hex strings: <446174653a>
  const hexRegex = /<([0-9a-fA-F]+)>/g;
  let hMatch: RegExpExecArray | null;
  while ((hMatch = hexRegex.exec(combinedContent)) !== null) {
    textTokens.push(decodeHexPdfString(hMatch[1]));
  }

  // Match standard parens: (Text)
  const parenRegex = /\(([^)]+)\)/g;
  let pMatch: RegExpExecArray | null;
  while ((pMatch = parenRegex.exec(combinedContent)) !== null) {
    textTokens.push(pMatch[1]);
  }

  return textTokens.join("");
}

describe("Phase 7 Part 3: s.63(4) Certificate & Route Tests", () => {
  const mockCaptureId = "cap_cert_test_777";
  const mockOwnerUid = "owner_alice_999";
  const mockManifestSha256 = "111122223333444455556666777788889999aaaabbbbccccddddeeeeffff0000";

  const mockArtifacts = [
    {
      id: "art_fullpage_screenshot",
      kind: "fullpage_screenshot" as const,
      mime: "image/png",
      bytes: 204800,
      sha256: "aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa",
      cid: "bafy_art_1",
      capturedAt: "2026-11-12T15:00:00Z",
    },
    {
      id: "art_page_pdf",
      kind: "page_pdf" as const,
      mime: "application/pdf",
      bytes: 102400,
      sha256: "bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb",
      cid: "bafy_art_2",
      capturedAt: "2026-11-12T15:00:01Z",
    },
    {
      id: "art_dom_html",
      kind: "dom_html" as const,
      mime: "text/html",
      bytes: 40960,
      sha256: "cccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccccc",
      cid: "bafy_art_3",
      capturedAt: "2026-11-12T15:00:02Z",
    },
    {
      id: "art_network_log",
      kind: "network_log" as const,
      mime: "application/json",
      bytes: 8192,
      sha256: "dddddddddddddddddddddddddddddddddddddddddddddddddddddddddddddddd",
      cid: "bafy_art_4",
      capturedAt: "2026-11-12T15:00:03Z",
    },
    {
      id: "art_tls_info",
      kind: "tls_info" as const,
      mime: "application/json",
      bytes: 256,
      sha256: "eeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeeee",
      cid: "bafy_art_5",
      capturedAt: "2026-11-12T15:00:04Z",
    },
  ];

  const mockManifest: EvidenceManifest = {
    schema: "saakshi.evidence/v1",
    captureId: mockCaptureId,
    previousCaptureId: null,
    requester: {
      uidHash: "hash_user_alice",
    },
    target: {
      url: "https://chirp.local/sandbox/post/internship-scam-alert",
      finalUrl: "https://chirp.local/sandbox/post/internship-scam-alert",
      goal: "Preserve scam post with fees",
      mode: "standard",
    },
    time: {
      serverStartedAt: "2026-11-12T15:00:00.000Z",
      serverFinishedAt: "2026-11-12T15:00:10.000Z",
    },
    tools: {
      saakshiVersion: "0.1.0",
      gitCommit: "commit_test_hash",
      tinyfish: {
        agentRunId: "run_tinyfish_mock_123",
        browserSessionId: "sess_browser_mock_456",
      },
    },
    observed: {
      title: "Internship Alert",
      author: "Scammer",
      publishedAtText: "2 hours ago",
      contentHash: "ffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffffff",
    },
    artifacts: mockArtifacts,
    hashAlgorithm: "SHA-256",
    encryption: "AES-256-GCM (cid refers to ciphertext; sha256 refers to plaintext)",
  };

  const origEnv = { ...process.env };

  beforeEach(async () => {
    process.env = { ...origEnv };
    process.env.NEXT_PUBLIC_APP_URL = "http://localhost:3000";

    await saveCaptureRecord(mockCaptureId, {
      id: mockCaptureId,
      ownerUid: mockOwnerUid,
      url: mockManifest.target.url,
      finalUrl: mockManifest.target.finalUrl,
      status: "READY",
      manifest: mockManifest,
      manifestSha256: mockManifestSha256,
      anchoring: null,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString(),
    });
  });

  afterEach(() => {
    process.env = { ...origEnv };
  });

  it("asserts manifest hash and every artifact hash are present in the PDF", async () => {
    const pdfBuffer = await renderCertificatePdf(mockManifest, mockManifestSha256, null, null);
    expect(pdfBuffer).toBeInstanceOf(Buffer);
    expect(pdfBuffer.length).toBeGreaterThan(1000);

    const extractedText = extractPdfText(pdfBuffer);

    // Assert manifest hash is present
    expect(extractedText).toContain(mockManifestSha256);

    // Assert EVERY artifact hash is present
    for (const art of mockArtifacts) {
      expect(extractedText).toContain(art.sha256);
    }
  });

  it("asserts declarant fields are blank for the party to sign", async () => {
    const pdfBuffer = await renderCertificatePdf(mockManifest, mockManifestSha256, null, null);
    const extractedText = extractPdfText(pdfBuffer);

    // Declarant field labels must be present
    expect(extractedText.toUpperCase()).toContain("PARTICULARS OF DECLARANT");
    expect(extractedText).toContain("Full Name of Declarant");
    expect(extractedText).toContain("Son / Daughter / Spouse of");
    expect(extractedText).toContain("Residential / Official Address");
    expect(extractedText).toContain("Contact");

    // Must NOT contain dummy or pre-filled person names
    expect(extractedText).not.toContain("John Doe");
    expect(extractedText).not.toContain("Jane Doe");
    expect(extractedText).not.toContain(mockOwnerUid);
  });

  it("asserts footer disclaimer and page numbers are present", async () => {
    const pdfBuffer = await renderCertificatePdf(mockManifest, mockManifestSha256, null, null);
    const extractedText = extractPdfText(pdfBuffer);

    // Mandatory legal disclaimer on every page
    expect(extractedText).toContain(MANDATORY_PAGE_DISCLAIMER);
    expect(extractedText).toContain("Generated by Saakshi as a drafting aid");
    expect(extractedText).toContain("Not legal advice");
    expect(extractedText).toContain("Part B must be completed by a qualified expert");
  });

  it("asserts SHA256 algorithm box is checked and ASCII line is present", async () => {
    const pdfBuffer = await renderCertificatePdf(mockManifest, mockManifestSha256, null, null);
    const extractedText = extractPdfText(pdfBuffer);

    expect(extractedText).toContain("[X] SHA256");
    expect(extractedText).toContain("[ ] SHA1");
    expect(extractedText).toContain("[ ] MD5");
  });

  it("asserts 'Not yet anchored' is displayed when capture is unanchored", async () => {
    const pdfBuffer = await renderCertificatePdf(mockManifest, mockManifestSha256, null, null);
    const extractedText = extractPdfText(pdfBuffer);

    expect(extractedText).toContain("Not yet anchored");
    expect(extractedText).not.toContain("0xmock");
  });

  it("never shows mock transactions even if mock txHash is present in anchoring record", async () => {
    const mockAnchoring = {
      txHash: "0xmock_tx_abcdef1234567890abcdef1234567890abcdef1234567890",
      root: "0xroot1234567890abcdef1234567890abcdef1234567890",
      blockNumber: 12345,
      anchoredAt: "2026-11-12T15:05:00Z",
      contract: "0x1234567890123456789012345678901234567890",
      chainId: 80002,
    };

    const pdfBuffer = await renderCertificatePdf(mockManifest, mockManifestSha256, mockAnchoring, null);
    const extractedText = extractPdfText(pdfBuffer);

    // Mock transaction hash must NEVER appear in the certificate PDF
    expect(extractedText).not.toContain("0xmock");
    expect(extractedText).not.toContain(mockAnchoring.txHash);
    expect(extractedText).toContain("Not yet anchored");
  });

  it("displays local test chain label for local chain anchoring", async () => {
    const localAnchoring = {
      txHash: "0x7777888899990000111122223333444455556666777788889999000011112222",
      root: "0x9999888877776666555544443333222211110000999988887777666655554444",
      blockNumber: 42,
      anchoredAt: "2026-11-12T15:10:00Z",
      contract: "0x0000000000000000000000000000000000000001",
      chainId: 31337,
    };

    const pdfBuffer = await renderCertificatePdf(mockManifest, mockManifestSha256, localAnchoring, null);
    const extractedText = extractPdfText(pdfBuffer);

    expect(extractedText).toContain("local test chain");
    expect(extractedText).toContain(localAnchoring.txHash);
    expect(extractedText).toContain(localAnchoring.root);
    expect(extractedText).toContain("How to Verify Independently");
  });

  it("route test: returns 404 for unknown capture", async () => {
    const req = new NextRequest("http://localhost:3000/api/captures/cap_nonexistent/certificate");
    const res = await certificateRouteHandler(req, { params: { id: "cap_nonexistent" } });
    expect(res.status).toBe(404);
  });

  it("route test: only the owner can download the certificate (403 for unauthorized users)", async () => {
    // Attempt download as an unauthorized user
    const reqUnauthorized = new NextRequest(
      `http://localhost:3000/api/captures/${mockCaptureId}/certificate`,
      {
        headers: {
          "x-user-uid": "attacker_bob_999",
        },
      }
    );
    const resUnauthorized = await certificateRouteHandler(reqUnauthorized, {
      params: { id: mockCaptureId },
    });
    expect(resUnauthorized.status).toBe(403);
    const data = await resUnauthorized.json();
    expect(data.error).toContain("Only the owner of this capture can download");

    // Attempt download as the authorized owner
    const reqAuthorized = new NextRequest(
      `http://localhost:3000/api/captures/${mockCaptureId}/certificate`,
      {
        headers: {
          "x-user-uid": mockOwnerUid,
        },
      }
    );
    const resAuthorized = await certificateRouteHandler(reqAuthorized, {
      params: { id: mockCaptureId },
    });
    expect(resAuthorized.status).toBe(200);
    expect(resAuthorized.headers.get("Content-Type")).toBe("application/pdf");
    expect(resAuthorized.headers.get("Content-Disposition")).toContain(
      `certificate_part_a_draft_${mockCaptureId}.pdf`
    );
  });
});
